using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
namespace DragonTower.Editor {
 public static class HydraSetup {
  public const string SkillPath="Assets/Data/Skills/skill_hydra.asset",Folder="Assets/Art/Hydra";
  public static void Install(){var headImport=(TextureImporter)AssetImporter.GetAtPath("Assets/Resources/Hydra/HeadParts.png");headImport.textureType=TextureImporterType.Default;headImport.filterMode=FilterMode.Point;headImport.mipmapEnabled=false;headImport.alphaIsTransparency=true;headImport.textureCompression=TextureImporterCompression.Uncompressed;headImport.maxTextureSize=1024;headImport.SaveAndReimport();Directory.CreateDirectory(Folder);Icon();AssetDatabase.Refresh();var imp=(TextureImporter)AssetImporter.GetAtPath(Folder+"/Icon.png");imp.textureType=TextureImporterType.Sprite;imp.spriteImportMode=SpriteImportMode.Single;imp.filterMode=FilterMode.Point;imp.mipmapEnabled=false;imp.textureCompression=TextureImporterCompression.Uncompressed;imp.SaveAndReimport();var s=AssetDatabase.LoadAssetAtPath<SkillData>(SkillPath);if(s==null){s=ScriptableObject.CreateInstance<SkillData>();s.damage=600;s.cooldown=24;s.initialHitDelay=3.4f;s.castLockDuration=4.7f;AssetDatabase.CreateAsset(s,SkillPath);}s.skillId="skill_hydra";s.displayName="히드라";s.description="베놈 전용 · 심연의 세 머리가 적을 포식합니다. 적중 후 5초간 중독 피해 주기 50% 단축. 중첩 없이 지속시간 갱신.";s.exclusiveDragonId="venom";s.elementType=ElementType.Dark;s.effectKind=SkillEffectKind.Dark;s.rarity=ContentRarity.Legendary;s.hydraPresentation=true;s.poisonAccelerationDuration=5;s.poisonIntervalFactor=.5f;s.hitCount=1;s.icon=AssetDatabase.LoadAssetAtPath<Sprite>(Folder+"/Icon.png");EditorUtility.SetDirty(s);var d=AssetDatabase.LoadAssetAtPath<DragonData>("Assets/Data/Dragon14.asset");d.signatureSkill=s;EditorUtility.SetDirty(d);var db=AssetDatabase.LoadAssetAtPath<ContentDatabase>("Assets/Resources/ContentDatabase.asset");if(!db.skills.Contains(s)){db.skills=db.skills.Concat(new[]{s}).ToArray();EditorUtility.SetDirty(db);}AssetDatabase.SaveAssets();Debug.Log("HYDRA_INSTALLED");}
  static void Icon(){const int n=128;var tex=new Texture2D(n,n,TextureFormat.RGBA32,false);var colors=new Color[n*n];for(int y=0;y<n;y++)for(int x=0;x<n;x++){float px=(x-64)/60f,py=(y-64)/60f;float r=px*px+py*py;Color c=r>1?Color.clear:new Color(.025f,.006f,.05f);float edge=Mathf.Abs(px)-(.82f-Mathf.Abs(py)*.45f+.04f*Mathf.Sin(y*.55f));if(r<1&&Mathf.Abs(edge)<.045f)c=new Color(.45f,.85f,.07f);for(int h=0;h<3;h++){float cx=h==0?0:h==1?-.48f:.48f,cy=h==0?.35f:-.1f;float dx=px-cx,dy=py-cy,size=h==0?.29f:.23f;if(Mathf.Abs(dx)<size*.55f&&dy<0&&dy>-.65f)c=new Color(.13f,.025f,.23f);if(Mathf.Abs(dx)<size&&Mathf.Abs(dy)<size*.8f)c=new Color(.23f,.055f,.36f);if(Mathf.Abs(dx)<size*.8f&&dy<-.1f&&dy>-.23f)c=new Color(.035f,.012f,.07f);if(Mathf.Abs(Mathf.Abs(dx)-size*.52f)<.052f&&Mathf.Abs(dy-.04f)<.032f)c=new Color(.7f,1,.12f);}colors[y*n+x]=c;}tex.SetPixels(colors);tex.Apply();File.WriteAllBytes(Folder+"/Icon.png",tex.EncodeToPNG());Object.DestroyImmediate(tex);}
 }
